<template><div class="office-page"><AppSidebar/><main class="main"><header class="head"><div><h2>办公看板</h2><p>部门推进、跨组风险与 AI 办公辅助</p></div><el-button size="small" @click="load">刷新数据</el-button></header><div class="metrics"><div v-for="x in cards" :key="x.label" :class="x.color"><span>{{x.label}}</span><b>{{x.value}}</b><small>{{x.note}}</small></div></div><div class="grid"><section class="panel"><h3>小组推进概览</h3><div v-for="g in groups" :key="g.id" class="group"><span>{{g.name}}</span><el-progress :percentage="progress(g)" :color="color(g)"/><b>{{memberCount(g.id)}} 人</b></div><h3>跨组风险清单</h3><el-table :data="risks" size="mini"><el-table-column prop="title" label="事项"/><el-table-column prop="start_time" label="截止时间" width="150"/><el-table-column label="状态" width="90"><template><el-tag size="mini" type="danger">逾期</el-tag></template></el-table-column></el-table></section><aside class="panel ai"><h3>AI 办公助手</h3><p>AI 只生成可编辑草稿，人工流程仍可独立完整运行。</p><el-button type="primary" size="small" @click="prompt('weekly')">生成部门周报</el-button><el-button size="small" @click="prompt('ppt')">生成 PPT 大纲</el-button><el-divider></el-divider><h3>待关注事项</h3><div v-for="n in notices.slice(0,5)" :key="n.id" class="notice"><el-tag size="mini" :type="n.is_read?'info':'warning'">{{n.notification_type}}</el-tag><span>{{n.title}}</span></div></aside></div><el-dialog title="AI 办公任务提示词" :visible.sync="visible" width="620px"><el-input v-model="text" type="textarea" :rows="11"/><span slot="footer"><el-button @click="copy">复制提示词</el-button></span></el-dialog></main></div></template>
<script>import AppSidebar from '../components/Sidebar/index.vue';export default{components:{AppSidebar},data:()=>({visible:false,text:''}),computed:{ws(){return this.$store.getters['workspace/activeWorkspace']||{}},d(){return this.$store.state.office.dashboard||{}},groups(){return(this.$store.state.office.organization||{groups:[]}).groups},members(){return(this.$store.state.office.organization||{members:[]}).members},notices(){return this.$store.state.office.notifications},risks(){return this.$store.state.office.schedules.filter(x=>x.event_type==='task'&&x.start_time&&new Date(x.start_time)<new Date()).slice(0,5)},cards(){let a=this.d.action_items||{},ds=this.d.documents_by_status||{};return[{label:'本周会议',value:this.d.meetings_this_week||0,note:'含跨组会议',color:'blue'},{label:'待处理审批',value:this.d.pending_approvals||0,note:'需及时流转',color:'orange'},{label:'任务完成率',value:(a.completion_rate||0)+'%',note:'逾期 '+(a.overdue||0)+' 项',color:'green'},{label:'已发布公文',value:ds.published||0,note:'正式通知归档',color:'purple'}]}},watch:{'ws.id':{immediate:true,handler(){this.load()}}},methods:{load(){if(this.ws.id&&this.ws.domain==='office')return Promise.all(['loadDashboard','loadOrganization','loadNotifications','loadSchedules'].map(x=>this.$store.dispatch('office/'+x,this.ws.id)))},memberCount(id){return this.members.filter(x=>x.group_id===id).length},progress(g){return Math.max(25,Math.min(95,45+this.memberCount(g.id)*12))},color(g){return ['#4d91ec','#42b883','#c37ddd'][this.groups.indexOf(g)%3]},prompt(k){this.text=k==='weekly'?'请依据部门会议、任务、审批和公文数据，生成部门周报：包括各小组进展、跨组协同、风险与下周计划。':'请依据部门本周工作数据，生成 5 页 PPT 大纲：总体进展、各小组成果、跨组协同、风险、下周计划。';this.visible=true},async copy(){try{await navigator.clipboard.writeText(this.text);this.$message.success('已复制')}catch(e){}}}}</script><style scoped>.office-page{display:flex;min-height:100vh;padding:12px;gap:12px;background:#f3f6fb}.main{flex:1;padding:20px;background:#fff;border-radius:12px}.head{display:flex;justify-content:space-between;border-bottom:1px solid #edf0f5;padding-bottom:14px}.head h2{margin:0 0 5px}.head p{margin:0;color:#8492a6}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:14px 0}.metrics>div{padding:13px;border-radius:8px;color:#fff}.metrics span,.metrics small{display:block}.metrics b{font-size:26px;margin:5px 0;display:block}.blue{background:#4d91ec}.orange{background:#df9d42}.green{background:#42b883}.purple{background:#9175d6}.grid{display:grid;grid-template-columns:1.5fr 1fr;gap:14px}.panel{border:1px solid #e7edf5;border-radius:9px;padding:14px}.panel h3{margin:0 0 12px}.group{display:grid;grid-template-columns:120px 1fr 45px;align-items:center;gap:8px;margin-bottom:12px}.ai p{font-size:13px;color:#778398;line-height:1.7}.notice{display:flex;gap:8px;padding:8px 0;border-bottom:1px dashed #e7edf5;font-size:13px}@media(max-width:900px){.metrics{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}}</style>
